local ActivityMountainDrawDialog = Class("ActivityMountainDrawDialog")
local TabCellPath = "Game.UI.ActivityMountain.Cell.ActivityMountainDrawTabCell"
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
