function ActivityMountainDrawDialog:AddUIClick()
	SetButtonAction(self.BtnTenNode.gameObject,Bind(self,self.OnBtnTenNodeClick))
	SetButtonAction(self.BtnOneNode.gameObject,Bind(self,self.OnBtnOneNodeClick))
	SetButtonAction(self.BtnDesc.gameObject,Bind(self,self.OnBtnDescClick))
	SetListViewAction(self.TabSv, Bind(self, self.OnUpdateTabListCellHandler_), TabCellPath)
end

function ActivityMountainDrawDialog:InitNodeEnv()
	self.nodeEnv = {}
	for i = 1, RewardCount do
		local node = self["NormalReward"..i]
		if not isNull(node) then
			local env = CfUtils.GetLuaScr(node,ShopCellPath)
			if not isNull(env) then
				table.insert(self.nodeEnv,env)
