function ActivityMountainDrawDialog:RefreshShow()
	self.activityDojo =  ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
	self.tabData = self.activityDojo:GetShopData()
	GameUtils.ReloadData(self.TabSv, #self.tabData)
	
	local index = 1
	local nowPoolId = self.activityDojo:GetNowPoolId()
	for i, v in pairs(self.tabData) do
		if v.id == nowPoolId then
			index = i
			break
		end
	end
	
	self:PreSelect(index)
	self:RefreshTimeShow()
	CfUtils.RefreshTopGoods({ table.takeFirst(self.tabData[index].consume).goodsId})
end

function ActivityMountainDrawDialog:RefreshTimeShow()
	local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
	--os.date("%m月%d日%H:%M", activityData.closeTime)
	local date = timestamp_to_time(activityData.closeTime)
	local showTxt = localize("_Y_年_M_月_D_日_H_:_S_以前",{_Y_ = date.year, _M_ = date.month,_D_ = date.day,_H_ = date.hour,_S_= date.min})
	CfUtils.FillText(self.TextTime,showTxt)
end

function ActivityMountainDrawDialog:OnUpdateTabListCellHandler_(listView, index, row, column)
	local cell = listView:NewListViewItem("Cell")
	if not isNull(cell) then
		local env = CfUtils.GetLuaScr(cell, TabCellPath)
		if not isNull(env) then
			local data = self.tabData[index]
			env:SetCallBackAndIndex(Bind(self,self.OnTabCellClick),index)
			env:RefreshShow(data)
		end
	end
	return cell
end

function ActivityMountainDrawDialog:OnTabCellClick(index)
	if self.tabIndex ~= nil and self.tabIndex == index then
		return
	end
	
	if not isNull(self.tabIndex) then
		self:SetSelectStatus(self.tabIndex,false)
	end
	
	self.tabIndex = index
	self:SetSelectStatus(self.tabIndex,true)
	self:RefreshShopShow()
end

function ActivityMountainDrawDialog:RefreshShopShow()
	self:RefreshShopItemShow()
	self:RefreshStock()
	self:RefreshBtnStatus()
end

function ActivityMountainDrawDialog:RefreshStock()
	if self.tabData[self.tabIndex].isLimit == 1 then
		CfUtils.SetActive(self.Stock.gameObject,false)
		return
	end
	CfUtils.SetActive(self.Stock.gameObject,true)
	local totalStock = 0
	local curStock = 0
	for i, v in pairs(self.tabData[self.tabIndex].list) do
		totalStock = totalStock + v.stock
		curStock = curStock + v.currentStock
	end
	CfUtils.FillText(self.StockNum,string.format("%s/%s",curStock,totalStock))
end

function ActivityMountainDrawDialog:RefreshBtnStatus()
	local consumeGold = table.takeFirst(self.tabData[self.tabIndex].consume)
	CfUtils.SetActive(self.OneCommonBtnConsumePop.gameObject, consumeGold ~= nil)
	if consumeGold ~= nil then
		UICommonUtils.FillCommonBtnConsumePop(self.OneCommonBtnConsumePop, consumeGold.goodsId, consumeGold.num)
	end
	
	CfUtils.SetActive(self.TenCommonBtnConsumePop.gameObject, consumeGold ~= nil)
	if consumeGold ~= nil then
		UICommonUtils.FillCommonBtnConsumePop(self.TenCommonBtnConsumePop, consumeGold.goodsId, consumeGold.num * 10 )
	end
end

function ActivityMountainDrawDialog:RefreshShopItemShow()
	local shopData = self.tabData[self.tabIndex].list
	for i, v in pairs(self.nodeEnv) do
		if not isNull(shopData[i]) then
			self.nodeEnv[i]:RefreshItemShow(shopData[i])
		end
	end
end

function ActivityMountainDrawDialog:SetSelectStatus(index,status)
	local cellItem = self.TabSv:GetShownItemByItemIndex(index - 1)
	if not isNull(cellItem) then
		local env = CfUtils.GetLuaScr(cellItem,TabCellPath)
		if not isNull(env) then
			env:SetSelectStatus(status)
		end
	end
end

function ActivityMountainDrawDialog:PreSelect(index)
	local cellItem = self.TabSv:GetShownItemByItemIndex(index - 1)
	if not isNull(cellItem) then
		local env = CfUtils.GetLuaScr(cellItem,TabCellPath)
		if not isNull(env) then
			env:OnTabCellClick()
		end
	end
end

-----------------------------------------
function ActivityMountainDrawDialog:OnBtnTenNodeClick()
	self:StartLuckyDraw(false)
end

function ActivityMountainDrawDialog:OnBtnOneNodeClick()
	self:StartLuckyDraw(true)
end

function ActivityMountainDrawDialog:OnBtnDescClick()
	local vo = ActivityCakeUtils.GetActivityParamsVo(10)
	if not isNull(vo) and checkNumber(vo.num) > 0 then
		CfUtils.ShowModuleToast(checkNumber(vo.num))
	end
end

function ActivityMountainDrawDialog:StartLuckyDraw(isOne)
	local consumeGold = table.takeFirst(self.tabData[self.tabIndex].consume)
	if not isNull(consumeGold) then
		local stock = self:GetTotalStock()
		if stock <= 0 then
			GameUtils.Toast(localize("库存不足"))
			return
		end
		
		local num = isOne and checkNumber(consumeGold.num) or self:GetCostNum(stock,consumeGold.num)
		local isEnough = GoodsUtils.GetThingNo(consumeGold.goodsId) >= num
		if not isEnough then
			GameUtils.Toast(localize("货币不足"))
			return
		end
		
		local activityData = ActivityCakeUtils.GetActivityCakeMgr():GetActivityData()
		GameUtils.Request(Interfaces.OverseaActivityCatParadiseLuckyDraw,{activityUuid = activityData.id,poolId = self.tabData[self.tabIndex].id,num = isOne and 1 or math.min(stock,10) },function(request,response)
			if checkInt(response.errCode) == 0 then
				local responseData = response.data
				if table.count(responseData.rewards) > 0 then
					GoodsUtils.DrawRewards({ { goodsId = consumeGold.goodsId, num = -num }},true)
					GoodsUtils.DrawRewards(responseData.rewards)
					UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewardIds } })
					
					self:UpdateItemStockAndPool(responseData.nowStock,responseData.nowPoolId)
				else
					GoodsUtils.DrawRewards({ { goodsId = consumeGold.goodsId, num = -num }})
				end
				
				self:RefreshShopShow()
				self:RefreshTagShow()
			end
		end)
	end
end

function ActivityMountainDrawDialog:GetCostNum(stock,num)
	local needStock = math.min(stock, 10)
	return checkNumber(num) * needStock
end

function ActivityMountainDrawDialog:RefreshTagShow()
	GameUtils.ReloadData(self.TabSv, #self.tabData)
	self:SetSelectStatus(self.tabIndex,true)
end

function ActivityMountainDrawDialog:UpdateItemStockAndPool(rewards,nowPoolId)
	self.activityDojo:UpdateItemStockAndPool(rewards, self.tabIndex,nowPoolId)
end

function ActivityMountainDrawDialog:GetTotalStock()
	local curStock = 0
	for i, v in pairs(self.tabData[self.tabIndex].list) do
		if v.currentStock == -1 then
			curStock = curStock + 999999
		else
			curStock = curStock + v.currentStock
		end
	
	end
	return curStock
end

return ActivityMountainDrawDialog